from sys import stdin, stdout
(n, k) = map(int, stdin.readline().rstrip().split())
print(2 + (n - 2) // k + (n - 3) // k)
connectionsList = []
for i in range(k):
	connectionsList.append((str(1), str(i + 2)))
for i in range(k + 2, n + 1):
	connectionsList.append((str(i - k), str(i)))
for conn in connectionsList:
	print(' '.join(conn))
